<?php

declare(strict_types=1);

namespace App\Enums;

use App\Enums\Concerns\EnumHelpers;

enum AttendanceSource: string
{
    use EnumHelpers;

    case Manual = 'manual';
    case Biometric = 'biometric';
    case Web = 'web';
    case Mobile = 'mobile';
    case Api = 'api';
    // Records generated by the engine itself (e.g. absences when a day is closed).
    case System = 'system';

    public function label(): string
    {
        return match ($this) {
            self::Manual => 'Manual',
            self::Biometric => 'Biometric',
            self::Web => 'Web',
            self::Mobile => 'Mobile',
            self::Api => 'API',
            self::System => 'System',
        };
    }
}
